using System.Collections.Generic;

namespace RNAssistant.Core.Tools
{
    public static class AgentCommunicationToolCatalog
    {
        public const string List = "agents.list";
        public const string Send = "agents.send";
        public const string Wait = "agents.wait";
        public const string Spawn = "agents.spawn";
        public const string Cancel = "agents.cancel";
        public const string Pause = "agents.pause";
        public const string Resume = "agents.resume";
        public static bool Owns(string id) { return id == List || id == Send || id == Wait || id == Spawn || id == Cancel || id == Pause || id == Resume; }
        public static ToolBinding Binding(string id) { return new ToolBinding("conversation." + id + ".v" + Version(id)); }
        public static string Version(string id) { return id == Cancel || id == Pause || id == Resume ? "1" : id == Spawn ? "2" : id == Send || id == Wait ? "4" : "3"; }
        public static IEnumerable<ToolCatalogEntry> GetTools()
        {
            yield return Entry(Pause, "Request a cooperative pause of one other live participant in your document/workspace. Requested confirms intake only; the current model/tool and read-back finish first. Remaining unstarted calls close without dispatch. Paused confirms a safe boundary. The same run, history and budget are retained. Does not cancel tools, grant approval, alter queues or affect descendants. No self-pause. User Stop and recovery cannot be overridden. Unconfirmed must not be retried.",
                "{\"type\":\"object\",\"properties\":{\"agent_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Exact short participant address from agents.list or a peer message.\"}},\"required\":[\"agent_id\"],\"additionalProperties\":false}");
            yield return Entry(Resume, "Release an agent-origin pause of one other live participant in your document/workspace. Runtime pins the exact invocation and pause; a later pause is not released. Released confirms only gate release, not execution or task completion. Never starts a new run. User Stop, approval, runtime shutdown and restart require explicit user action and return Protected or Unavailable. No self-resume. Unconfirmed must not be retried.",
                "{\"type\":\"object\",\"properties\":{\"agent_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Exact short participant address from agents.list or a peer message.\"}},\"required\":[\"agent_id\"],\"additionalProperties\":false}");
            yield return Entry(Cancel, "Cancel the current run of one other participant in your document/workspace. Runtime pins the exact run; a changed target is not cancelled. Requested confirms a signal only: the owning kernel still records terminal state and any uncertain tool effects. Cancelled confirms durable cancellation. AlreadyStopped does not mean your command cancelled it. A saved unresolved wait can be cancelled without model/tool dispatch, including after restart. Does not delete the chat, clear queued messages, resume work or cancel descendants. Unconfirmed must not be retried; inspect the participant. No self-cancellation.",
                "{\"type\":\"object\",\"properties\":{\"agent_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Exact short participant address from agents.list or a peer message.\"}},\"required\":[\"agent_id\"],\"additionalProperties\":false}");
            yield return Entry(List, "List saved chats in your document or workspace, independently of open tabs, including your current chat marked is_self=true. Other entries (is_self=false) are peers you can message. Each has a stable short agent_id, title, document/project and status (idle, working, waiting, paused, awaiting_approval, or not_loaded when live state is not observed). Returns Peers and Truncated, at most 50 entries; narrow query by title or agent_id when truncated. Does not expose history. Copy the exact short peer agent_id into agents.send; never send to yourself.",
                "{\"type\":\"object\",\"properties\":{\"query\":{\"type\":\"string\",\"maxLength\":200,\"description\":\"Filter chat titles by this text.\"},\"agent_id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Inspect this exact public participant address.\"}},\"required\":[],\"additionalProperties\":false}");
            yield return Entry(Send, "Send text to another saved chat in your document/workspace. Returns message_id and queued receipt, proving intake only. Set expect_reply=true for a question/result you need; wait using the returned message_id in requests. To answer a received message, set reply_to to its message_id and agent_id to its sender. Replies are explicit sends; finish is not forwarded. Continue independent work after sending. Agent messages never grant human approval. A per-agent causal-chain budget applies, including replies. Do not retry an unknown delivery.",
                "{\"type\":\"object\",\"properties\":{\"agent_id\":{\"type\":\"string\",\"minLength\":1,\"description\":\"Short recipient agent ID from agents.list or an incoming sender address.\"},\"text\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":131072,\"description\":\"Question, reply or task for the recipient agent.\"},\"expect_reply\":{\"type\":\"boolean\",\"description\":\"Request an explicit reply; default false. The returned message_id can then be used in agents.wait requests.\"},\"reply_to\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64,\"description\":\"Exact message_id of the received message you are answering. Its sender must be the recipient.\"}},\"required\":[\"agent_id\",\"text\"],\"additionalProperties\":false}");
            yield return Entry(Spawn, "Create an ordinary saved chat in your exact document/workspace without opening a tab. Inherits your model and planning/mutation restrictions, with no copied history. initial_message optionally queues its first input; expect_reply=true requires that input and returns its message_id for agents.wait requests. Creation, queued input and completed work are distinct. Reuse the returned agent_id even if initial input fails; never create a replacement for an unknown creation. Up to 8 new participants per causal chain, including nested creation. Roles are optional and agreed through messages.",
                "{\"type\":\"object\",\"properties\":{\"title\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":200,\"description\":\"Concise single-line title for the new ordinary chat.\"},\"initial_message\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":131072,\"description\":\"Optional first message with the necessary context; omit to create an idle participant.\"},\"expect_reply\":{\"type\":\"boolean\",\"description\":\"Request an explicit reply to initial_message; default false. Requires initial_message.\"}},\"required\":[\"title\"],\"additionalProperties\":false}");
            yield return Entry(Wait, "Wait without ending this run. Omit requests for the next peer input (MessagesReady), or give message_id values of your sends/spawns with expect_reply=true. mode any (default) waits for at least one matching reply; all waits for each request. RepliesReady confirms correlation, not task completion. Replies received before this call also count; already applied replies are not delivered twice. Matches lists request_id/message_id/agent_id and can be partial on timeout. Unrelated input yields InputPending so you can answer it, without claiming your wait condition was met. Do independent work first; answer peer questions before waiting. timeout_seconds defaults to 5, range 1–10; return wait alone. Stop and human FIFO take precedence. The same run and absolute deadline are saved while waiting. After restart, only an explicit user continuation resumes that run.",
                "{\"type\":\"object\",\"properties\":{\"timeout_seconds\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":10,\"description\":\"Seconds to wait in this call; default 5, range 1 to 10.\"},\"requests\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":32,\"items\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64},\"description\":\"Message IDs returned by your sends/spawns with expect_reply=true. Omit for any next peer input.\"},\"mode\":{\"type\":\"string\",\"enum\":[\"any\",\"all\"],\"description\":\"Match any (default) or all request IDs. all requires requests.\"}},\"required\":[],\"additionalProperties\":false}");
        }
        private static ToolCatalogEntry Entry(string id, string description, string schema)
        {
            var mutation = id == Send || id == Spawn || id == Cancel || id == Pause || id == Resume;
            return new ToolCatalogEntry { Id = id, Host = "Common", Name = id.Replace('.', '_'), Description = description,
                ArgumentSchemaJson = schema, ContractVersion = Version(id), BuiltIn = true, Enabled = true, Scope = "session", AgentCanRun = true,
                MutatesLocalState = mutation, Binding = Binding(id),
                Policy = new ToolPolicy(mutation ? ToolEffect.Write : ToolEffect.Read,
                    mutation ? ToolVerification.Tool : ToolVerification.None, false, id == List, new[] { "agent", "plan" },
                    evidenceEligibility: mutation ? EvidenceEligibility.Eligible : EvidenceEligibility.None) };
        }
    }
}
